{
  "schema_version": "agentto.spec/v0",
  "name": "sensor_arm",
  "description": "150 mm sensor arm along x carrying a 2 kg camera on a centered 20 x 20 mm end mounting plate.",
  "units": {
    "length": "mm",
    "force": "N"
  },
  "domain": {
    "kind": "box",
    "size": [150, 30, 30]
  },
  "material": {
    "name": "steel",
    "E": 210000,
    "nu": 0.3
  },
