  "supports": [
    {
      "id": "frame_attachment",
      "region": {
        "kind": "face",
        "face": "x-"
      },
      "fix": ["x", "y", "z"],
      "note": "Assumed fully clamped to the robot frame at x = 0."
    }
  ],
  "loads": [
    {
      "id": "camera_weight",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [15, 15],
        "size": [20, 20]
      },
      "force": [0, 0, -20],
      "distribution": "uniform_nodes",
      "note": "Camera weight distributed over the mounting footprint; gravity assumed along -z."
    }
  ],
  "resolution": {
    "h": 1
  }
